<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {PhGameController,PhMagnifyingGlass,PhPlay,PhFolderOpen,PhPencilSimple,PhHeart,PhClockCounterClockwise,PhSquaresFour,PhList,PhArrowsClockwise,PhSun,PhMoon,PhDesktop,PhMinus,PhSquare,PhX,PhCheckCircle,PhGearSix,PhArrowSquareOut,PhUploadSimple,PhCopy,PhCheck,PhSpinnerGap,PhDotsThree,PhWarningCircle,PhCaretRight} from '@phosphor-icons/vue'
import {call,library,windowAction,isDesktop,type Game,type Candidate,type Background,type ArtworkSettings} from './api'
import hero from './assets/wuxia-hero.png'
import appIcon from './assets/app-icon.png'
import ThemePicker from './ThemePicker.vue'
import ArtworkPicker from './ArtworkPicker.vue'
import ScanSettings from './ScanSettings.vue'
import ReviewCandidates from './ReviewCandidates.vue'
import './app.css'
import './glass.css'
import {vGlass} from './glass'
const games=ref<Game[]>([]),selectedID=ref(''),query=ref(''),tab=ref('all'),source=ref('all'),view=ref('grid')
const reviewOnly=ref(false),reviewSelection=ref('')
const pendingCount=computed(()=>games.value.filter(g=>g.review?.pending).length)
const theme=ref('system'),media=window.matchMedia('(prefers-color-scheme: dark)'),systemDark=ref(media.matches)
const loading=ref(true),busy=ref(''),notice=ref(''),error=ref(''),settings=ref(false),dataDir=ref(''),updated=ref('')
const editing=ref<Game|null>(null),editName=ref(''),editExe=ref(''),lookup=ref(''),provider=ref('steam'),candidates=ref<Candidate[]>([]),lookupMessage=ref('')
const backgroundQuery=ref(''),backgroundResult=ref<Background|null>(null),backgroundSummary=ref('')
const backgroundDone=ref(0),backgroundTotal=ref(0)
const scanActive=computed(()=>busy.value==='scan'||busy.value==='backgrounds')
const backgroundPercent=computed(()=>backgroundTotal.value?Math.round(backgroundDone.value/backgroundTotal.value*100):0)
const backgroundProvider=ref('steam'),apiKey=ref(''),apiMessage=ref(''),apiStatus=ref<ArtworkSettings>({configured:false,message:''})
const editTab=ref('basic'),menu=ref<{game:Game;x:number;y:number}|null>(null)
let returnFocus:HTMLElement|null=null
const themes=[{value:'light',name:'亮色',icon:PhSun},{value:'dark',name:'暗色',icon:PhMoon},{value:'system',name:'跟随系统',icon:PhDesktop}]
const effective=computed(()=>theme.value==='system'?(systemDark.value?'dark':'light'):theme.value)
watch(effective,v=>document.documentElement.dataset.theme=v,{immediate:true})
const systemChange=(e:MediaQueryListEvent)=>systemDark.value=e.matches
let toastTimer:ReturnType<typeof setTimeout>
function toast(s:string){notice.value=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>notice.value='',3800)}
function rank(g:Game){const i=['Blades of Jianghu','Slay the Spire','MahjongSoul','Star Rail','HumanResourceMachine','Pass The Fear'].findIndex(k=>(g.folder+' '+g.original_name).includes(k));return i<0?100:i}
const filtered=computed(()=>games.value.filter(g=>(!reviewOnly.value||g.review?.pending)&&(source.value==='all'||g.source===source.value)&&(tab.value!=='favorites'||g.favorite)&&(tab.value!=='recent'||g.last_played)&&[g.name,g.original_name,g.folder,g.exe,g.detected_appid].join(' ').toLowerCase().includes(query.value.toLowerCase())).sort((a,b)=>tab.value==='recent'?b.last_played.localeCompare(a.last_played):rank(a)-rank(b)||a.name.localeCompare(b.name,'zh-CN')))
const selected=computed(()=>games.value.find(g=>g.id===selectedID.value)||filtered.value[0]||null)
const wuxia=computed(()=>!selected.value?.hero_image&&selected.value?.folder.includes('Blades of Jianghu'))
const heroImage=computed(()=>wuxia.value?hero:selected.value?.hero_image||selected.value?.image||'')
const title=computed(()=>tab.value==='favorites'?'我的收藏':tab.value==='recent'?'最近游玩':'全部游戏')
watch(filtered,rows=>{if(rows.length&&!rows.some(g=>g.id===selectedID.value))selectedID.value=rows[0].id})
async function refresh(initial=false){const d=await library();const main=document.querySelector('main'),scroll=main?.scrollTop||0;games.value=d.games;dataDir.value=d.data_dir;updated.value=d.updated;if(initial){theme.value=d.theme||'system';selectedID.value=d.games.find(g=>g.folder.includes('Blades of Jianghu'))?.id||d.games[0]?.id||''}await nextTick();if(main&&!initial)main.scrollTop=scroll}
async function perform(key:string,fn:()=>Promise<void>){if(busy.value)return;busy.value=key;error.value='';try{await fn()}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=''}}
async function changeTheme(v:string){const old=theme.value;theme.value=v;try{await call('SetTheme',v)}catch(e){theme.value=old;toast('主题保存失败：'+String(e))}}
async function launch(g:Game|null=selected.value){if(!g)return;await perform('launch',async()=>{await call('LaunchGame',g.id,'');await refresh();toast('已启动 '+g.name)})}
async function openFolder(g:Game|null=selected.value){if(!g)return;await perform('folder',async()=>{await call('OpenFolder',g.id);toast('已定位启动程序，并尝试激活文件夹窗口')})}
async function favorite(g:Game){try{g.favorite=await call<boolean>('ToggleFavorite',g.id)}catch(e){toast(String(e))}}
function openEdit(g:Game|null=selected.value,section='basic'){if(!g||busy.value)return;returnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;editTab.value=section;reviewSelection.value='';backgroundProvider.value='steam';editing.value=g;editName.value=g.name;editExe.value=g.exe;lookup.value=g.detected_appid||g.metadata?.query||g.original_name.replace(/(?:[\s_(-]*)(?:ver(?:sion)?\.?|v)\s*\d+(?:\.\w+)*(?:[)\]]?)/ig,'').replace(/([a-z])([A-Z])/g,'$1 $2').trim();provider.value=g.metadata?.search_provider==='all'?'all':g.detected_appid?'steam':g.metadata?.search_provider||'all';candidates.value=g.metadata?.candidates||[];lookupMessage.value='';backgroundQuery.value=g.background?.appid||g.detected_appid||g.name;backgroundResult.value=g.background||null;error.value=''}
async function save(){if(!editing.value)return;await perform('save',async()=>{await call('SaveMetadata',editing.value!.id,editName.value,editExe.value);await refresh();editing.value=null;toast('名称和启动设置已保存')})}
async function upload(){if(!editing.value)return;await perform('upload',async()=>{if(await call<boolean>('ImportCover',editing.value!.id)){await refresh();editing.value=games.value.find(g=>g.id===editing.value!.id)||null;toast('新封面已保存')}})}
async function search(){if(!editing.value)return;await perform('search',async()=>{candidates.value=await call<Candidate[]>('SearchMetadata',editing.value!.id,lookup.value,provider.value)||[];lookupMessage.value=candidates.value.length?(provider.value==='dlsite'&&candidates.value.some(c=>c.provider.includes('备用'))?'DLsite 未返回可用结果，以下为 VNDB 备用候选，请核对作品后采用。':`找到 ${candidates.value.length} 个候选，请核对作品后采用。`):'没有找到候选，可更换原名、英文名或 AppID。';await refresh()})}
async function choose(c:Candidate){if(!editing.value)return;await perform('choose',async()=>{await call('UseCandidate',editing.value!.id,c.key);await refresh();editing.value=null;toast('名称和封面已更新')})}
async function confirmReview(){const c=candidates.value.find(c=>c.key===reviewSelection.value);if(c)await choose(c)}
async function keepReview(){if(!editing.value)return;await perform('keep-review',async()=>{await call('KeepMetadata',editing.value!.id);await refresh();editing.value=null;toast('已保留原资料')})}
async function reset(){if(!editing.value)return;await perform('reset',async()=>{await call('ResetMetadata',editing.value!.id);await refresh();editing.value=null;toast('已恢复扫描信息')})}
async function scan(){await perform('scan',async()=>{backgroundSummary.value='';backgroundDone.value=0;backgroundTotal.value=0;const result=await call<{note:string}>('ScanGames');await refresh();toast(result.note||'扫描完成，手动资料已保留');busy.value='backgrounds';await completeLibrary()})}
async function findBackground(){if(!editing.value)return;await perform('background',async()=>{backgroundResult.value=await call<Background>('FindBackground',editing.value!.id,backgroundQuery.value);await refresh();editing.value=games.value.find(g=>g.id===editing.value!.id)||null})}
async function chooseBackground(c:Candidate){if(!editing.value)return;await perform('background',async()=>{backgroundResult.value=await call<Background>('UseBackground',editing.value!.id,c.key.replace('steam:',''));await refresh();editing.value=games.value.find(g=>g.id===editing.value!.id)||null})}
async function fillBackgrounds(){await perform('backgrounds',completeLibrary)}
async function completeLibrary(){
 const pending=games.value.filter(g=>!g.has_cover||!g.hero_image||!g.metadata?.name);let cursor=0,done=0,names=0,covers=0,backgrounds=0,review=0,failed=0;backgroundSummary.value='';backgroundDone.value=0;backgroundTotal.value=pending.length;
 if(!pending.length){backgroundSummary.value='游戏名称、封面和背景均已齐全。';return}
 await Promise.all(Array.from({length:Math.min(3,pending.length)},async()=>{while(cursor<pending.length){const g=pending[cursor++];try{const result=await call<{name:boolean;cover:boolean;background:boolean;review:boolean;errors:string[]}>('EnrichGame',g.id);if(result.name)names++;if(result.cover)covers++;if(result.background)backgrounds++;if(result.review)review++;if(result.errors?.length)failed++}catch{failed++}done++;backgroundDone.value=done;if(done%6===0)await refresh()}}));await refresh();backgroundSummary.value=`本次补全 ${names} 个名称、${covers} 张封面、${backgrounds} 张背景${review?`，${review} 款需核对候选`:''}${failed?`，${failed} 款部分查询或下载失败，可稍后重试`:''}。未确认的资料保持原样。`
}
function artworkBusy(value:boolean){if(value)busy.value='artwork';else if(busy.value==='artwork')busy.value=''}
async function artworkUsed(kind:string){const id=editing.value?.id;await refresh();if(editing.value?.id===id)editing.value=games.value.find(g=>g.id===id)||null;toast(kind==='cover'?'封面已更新，名称保持不变':'背景图已更新')}
async function openSettings(){if(busy.value)return;settings.value=true;editing.value=null;closeMenu();apiKey.value='';apiMessage.value='';await nextTick();document.querySelector<HTMLElement>('.settings [aria-label="关闭设置"]')?.focus({preventScroll:true});try{apiStatus.value=await call<ArtworkSettings>('GetArtworkSettings')}catch(e){apiMessage.value=String(e)}}
async function saveAPI(){await perform('api-save',async()=>{apiStatus.value=await call<ArtworkSettings>('SaveSteamGridDBKey',apiKey.value);apiKey.value='';apiMessage.value='API Key 已加密保存'})}
async function testAPI(){await perform('api-test',async()=>{apiMessage.value=await call<string>('TestSteamGridDBKey',apiKey.value)})}
async function clearAPI(){await perform('api-clear',async()=>{apiStatus.value=await call<ArtworkSettings>('ClearSteamGridDBKey');apiKey.value='';apiMessage.value='API Key 已清除'})}
watch(settings,value=>{if(!value)apiKey.value=''})
async function copy(text:string){try{if(window.runtime?.ClipboardSetText)await window.runtime.ClipboardSetText(text);else await navigator.clipboard.writeText(text);toast('路径已复制')}catch{toast('复制失败')}}
function openURL(url:string){if(!/^https:\/\//.test(url))return;if(window.runtime?.BrowserOpenURL)window.runtime.BrowserOpenURL(url);else window.open(url,'_blank','noopener,noreferrer')}
watch(()=>!!editing.value||settings.value,async open=>{if(open){await nextTick();document.querySelector<HTMLElement>('[role=dialog] input,[role=dialog] button')?.focus({preventScroll:true})}})
watch(editing,async(value,old)=>{if(!value&&old&&!settings.value){await nextTick();returnFocus?.focus({preventScroll:true})}})
function closeMenu(restore=false){menu.value=null;if(restore)returnFocus?.focus({preventScroll:true})}
async function showMenu(g:Game,event:MouseEvent,context=false){if(busy.value)return;if(!context&&menu.value?.game.id===g.id){closeMenu(true);return}const target=event.currentTarget as HTMLElement;returnFocus=context?target.querySelector<HTMLElement>('.tile-select'):target;const rect=target.getBoundingClientRect();menu.value={game:g,x:Math.max(8,Math.min(context&&Number.isFinite(event.clientX)?event.clientX:rect.right-220,window.innerWidth-228)),y:Math.max(8,Math.min(context&&Number.isFinite(event.clientY)?event.clientY:rect.bottom+6,window.innerHeight-300))};await nextTick();document.querySelector<HTMLElement>('.game-menu button')?.focus({preventScroll:true})}
function menuAction(action:string){const g=menu.value?.game;if(!g)return;closeMenu(true);if(action==='launch')void launch(g);if(action==='folder')void openFolder(g);if(action==='favorite')void favorite(g);if(action==='edit'||action==='background')openEdit(g,action==='background'?'background':'basic')}
function menuKeys(e:KeyboardEvent){const items=Array.from(document.querySelectorAll<HTMLButtonElement>('.game-menu button'));const i=items.indexOf(document.activeElement as HTMLButtonElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();items[e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus({preventScroll:true})}if(e.key==='Escape'||e.key==='Tab'){e.preventDefault();e.stopPropagation();closeMenu(true)}}
function outsideMenu(e:PointerEvent){if(!(e.target as Element).closest('.game-menu,.card-more'))closeMenu()}
function keydown(e:KeyboardEvent){if(e.key==='Tab'&&(editing.value||settings.value)){const nodes=Array.from(document.querySelectorAll<HTMLElement>('[role=dialog] button:not([disabled]),[role=dialog] input:not([disabled]),[role=dialog] select:not([disabled]),[role=dialog] textarea:not([disabled])')).filter(node=>node.getClientRects().length>0);const first=nodes[0],last=nodes[nodes.length-1];if(!document.querySelector('[role=dialog]')?.contains(document.activeElement)){e.preventDefault();(e.shiftKey?last:first)?.focus({preventScroll:true})}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if(e.key==='Escape'&&!busy.value){editing.value=null;settings.value=false}if((e.ctrlKey||e.metaKey)&&e.key==='f'){e.preventDefault();document.querySelector<HTMLInputElement>('#search')?.focus()}}
function closeMenuOnResize(){closeMenu()}
onMounted(async()=>{media.addEventListener('change',systemChange);document.addEventListener('keydown',keydown);document.addEventListener('pointerdown',outsideMenu);window.addEventListener('resize',closeMenuOnResize);try{await refresh(true)}catch(e){error.value=String(e)}finally{loading.value=false}})
onUnmounted(()=>{media.removeEventListener('change',systemChange);document.removeEventListener('keydown',keydown);document.removeEventListener('pointerdown',outsideMenu);window.removeEventListener('resize',closeMenuOnResize);clearTimeout(toastTimer)})
</script>
<template>
 <div class="app-shell" :class="{'library-list':view==='list'}">
  <div v-if="heroImage&&(wuxia||selected?.hero_image)" class="scene-backdrop" aria-hidden="true"><img :key="heroImage" :src="heroImage" alt="" @error="($event.target as HTMLImageElement).style.opacity='0'"></div>
  <header class="titlebar" @dblclick="windowAction('WindowToggleMaximise')"><div class="brand"><img :src="appIcon" width="24" height="24" alt="" draggable="false"/><span>游栖 · GameNest</span></div><span v-if="!isDesktop()" class="preview-label">桌面版预览</span><div class="caption-controls"><button aria-label="最小化" @click="windowAction('WindowMinimise')"><PhMinus :size="14"/></button><button aria-label="最大化" @click="windowAction('WindowToggleMaximise')"><PhSquare :size="12"/></button><button class="close-window" aria-label="关闭窗口" @click="windowAction('Quit')"><PhX :size="17"/></button></div></header>
  <nav class="navigation"><div v-glass class="tabs"><button :class="{active:tab==='all'}" @click="tab='all'"><PhGameController :size="20" :weight="tab==='all'?'fill':'regular'"/>全部游戏</button><button :class="{active:tab==='recent'}" @click="tab='recent'"><PhClockCounterClockwise :size="20"/>最近游玩</button><button :class="{active:tab==='favorites'}" @click="tab='favorites'"><PhHeart :size="20" :weight="tab==='favorites'?'fill':'regular'"/>收藏</button></div><div class="nav-actions"><label v-glass class="search"><PhMagnifyingGlass :size="18"/><input id="search" v-model="query" aria-label="搜索游戏" placeholder="搜索游戏…"><span>Ctrl F</span></label><button v-glass class="scan-button" :disabled="!!busy" @click="scan"><PhArrowsClockwise :size="18" :class="{spinning:busy==='scan'}"/>{{busy==='scan'?'扫描中…':'扫描游戏'}}</button><ThemePicker :value="theme" @change="changeTheme"/></div></nav>
  <main @scroll="closeMenu()"><div v-if="loading" class="loading-state"><PhSpinnerGap :size="30" class="spinning"/>正在载入你的游戏…</div><template v-else>
   <section v-if="selected" class="hero" :class="{wuxia,panoramic:!!selected.hero_image,'poster-only':!wuxia&&!selected.hero_image}" aria-label="选中游戏详情"><img v-if="heroImage&&(wuxia||selected.hero_image||selected.has_cover)" :key="heroImage" class="hero-art" :src="heroImage" alt="" @error="($event.target as HTMLImageElement).style.opacity='0'"><div class="hero-fade"></div><div class="hero-content"><div class="selected-label"><span></span>你的下一段旅程</div><h1 :class="{calligraphy:wuxia}">{{selected.name}}</h1><p v-if="selected.original_name.toLowerCase().trim()!==selected.name.toLowerCase().trim()" class="original-name">{{selected.original_name!==selected.name?selected.original_name:selected.folder.split(/[\\/]/).filter(Boolean).pop()}}</p><div class="game-facts"><span><PhDesktop :size="16"/>{{selected.source}}</span><span v-if="selected.detected_appid">Steam <i></i>{{selected.detected_appid}}</span><span v-else-if="selected.metadata?.provider">{{selected.metadata.provider}}</span></div><div class="hero-actions"><button class="primary" :disabled="!!busy" @click="launch()"><PhPlay :size="19" weight="fill"/>{{busy==='launch'?'正在启动…':'开始游戏'}}</button><button v-glass class="secondary" :disabled="!!busy" @click="openFolder()"><PhFolderOpen :size="19"/>打开文件夹</button><button v-glass class="hero-edit" aria-label="编辑资料" title="编辑资料" @click="openEdit()"><PhPencilSimple :size="20"/></button><button v-glass class="favorite-hero" :class="{saved:selected.favorite}" :aria-label="selected.favorite?'取消收藏':'收藏游戏'" @click="favorite(selected)"><PhHeart :size="20" :weight="selected.favorite?'fill':'regular'"/></button></div></div></section>
   <section class="collection"><div class="collection-header"><div class="collection-heading"><h2>{{reviewOnly?'待确认游戏':title}}<span>{{filtered.length}}</span></h2><button v-if="pendingCount||reviewOnly" v-glass class="review-filter" :class="{active:reviewOnly}" :aria-pressed="reviewOnly" @click="reviewOnly=!reviewOnly"><PhWarningCircle :size="19" weight="fill"/>待确认 <b>{{pendingCount}}</b><PhX v-if="reviewOnly" :size="14"/></button></div><div class="collection-tools"><button class="scan-button" :disabled="!!busy" @click="fillBackgrounds"><PhSpinnerGap v-if="busy==='backgrounds'" :size="16" class="spinning"/><PhMagnifyingGlass v-else :size="16"/>{{busy==='backgrounds'?'补全中…':'补全游戏资料'}}</button><select v-model="source" aria-label="游戏来源"><option value="all">全部来源</option><option value="Steam">Steam</option><option value="Epic">Epic</option><option value="本地游戏">本地游戏</option></select><div v-glass class="view-switch"><button :class="{active:view==='grid'}" aria-label="封面视图" @click="view='grid'"><PhSquaresFour :size="20"/></button><button :class="{active:view==='list'}" aria-label="列表视图" @click="view='list'"><PhList :size="21"/></button></div></div></div>
   <section v-if="scanActive||backgroundSummary" v-glass class="scan-status" :class="{'scan-status-complete':!scanActive}" aria-label="游戏资料任务状态">
    <PhSpinnerGap v-if="scanActive" :size="26" class="scan-status-icon spinning" aria-hidden="true"/><PhCheckCircle v-else :size="23" class="scan-status-icon" aria-hidden="true"/>
    <div class="scan-status-content"><div class="scan-status-row"><div class="scan-status-copy" role="status"><strong>{{scanActive?(busy==='scan'?'正在扫描本地游戏':'正在补全游戏资料'):'资料检查完成'}}</strong><span>{{scanActive?(busy==='scan'?'正在查找扫描位置中的游戏':'查找名称、封面和背景'):backgroundSummary}}</span></div><div v-if="scanActive&&busy!=='scan'&&backgroundTotal" class="scan-status-count"><span>{{backgroundDone}} <small>/ {{backgroundTotal}}</small></span><b>{{backgroundPercent}}%</b></div></div>
     <div v-if="scanActive" class="scan-status-track" :class="{indeterminate:busy==='scan'||!backgroundTotal}" role="progressbar" :aria-label="busy==='scan'?'扫描本地游戏':'补全游戏资料'" :aria-valuenow="busy==='scan'||!backgroundTotal?undefined:backgroundDone" :aria-valuemax="busy==='scan'||!backgroundTotal?undefined:backgroundTotal" aria-valuemin="0"><span :style="{width:backgroundPercent+'%'}"></span></div>
    </div><button v-if="!scanActive" class="icon-button" aria-label="关闭资料检查结果" @click="backgroundSummary='' "><PhX :size="18"/></button>
   </section><div v-if="!filtered.length" class="empty-state"><PhMagnifyingGlass :size="36"/><h3>{{tab==='favorites'?'还没有收藏的游戏':tab==='recent'?'还没有启动记录':'没有找到匹配的游戏'}}</h3><p>{{tab==='recent'?'从这里启动游戏后，就会出现在最近游玩中。':'试试其他关键词、来源，或调整扫描范围后重新扫描。'}}</p><button class="secondary" @click="query='';source='all';tab='all';reviewOnly=false">查看全部游戏</button></div>
   <div v-else class="library-results">
    <div v-if="view==='list'" v-glass class="library-list-header" aria-hidden="true"><span>游戏名称</span><span>来源</span><span>资料状态</span><span>操作</span></div>
    <div class="game-grid" :class="{'list-mode':view==='list'}">
     <article v-for="g in filtered" :key="g.id" class="game-tile" :class="{selected:selectedID===g.id,'needs-review':g.review?.pending}" @contextmenu.prevent="showMenu(g,$event,true)" @keydown.shift.f10.prevent="showMenu(g,$event as unknown as MouseEvent,true)">
      <button class="tile-select" @click="selectedID=g.id" @dblclick="selectedID=g.id;launch(g)" :aria-label="'选择 '+g.name">
       <div class="cover-frame" :class="{'icon-art':!g.has_cover}"><img v-if="g.image" :key="g.image" :src="g.image" :alt="g.name+' 封面'" loading="lazy" @error="($event.target as HTMLImageElement).style.display='none'"><PhGameController v-else :size="50" weight="duotone"/><span class="tile-selected"><PhCheck :size="13" weight="bold"/></span><span v-if="g.favorite" class="tile-heart"><PhHeart :size="15" weight="fill"/></span><span class="tile-play"><PhPlay :size="22" weight="fill"/></span></div>
       <div class="tile-info"><h3 :title="g.name">{{g.name}}</h3><p>{{g.original_name!==g.name?g.original_name:g.source}}</p></div>
      </button>
      <button v-if="g.review?.pending&&view==='grid'" v-glass class="review-badge" :disabled="!!busy" :aria-label="g.name+' 待确认，核对候选'" @click.stop="openEdit(g,'review')"><PhWarningCircle :size="15" weight="fill"/>待确认</button>
      <span v-if="view==='list'" class="list-source">{{g.source}}</span>
      <div v-if="view==='list'||g.review?.pending" class="match-status" :class="{pending:g.review?.pending}">
       <template v-if="g.review?.pending"><strong><PhWarningCircle v-if="view==='list'" :size="19" weight="fill"/>{{view==='list'?'待确认 · ':''}}{{g.review.count}} 个候选</strong><small>{{g.review.reason}}</small></template>
       <span v-else class="match-settled"><PhCheckCircle v-if="g.metadata?.source_url" :size="18"/>{{g.metadata?.review_decision==='kept'?'已保留原资料':g.metadata?.source_url?'已匹配':'本地资料'}}</span>
      </div>
      <button v-if="g.review?.pending" v-glass class="review-action" :disabled="!!busy" @click.stop="openEdit(g,'review')">核对候选<PhCaretRight :size="14"/></button>
      <div class="card-actions"><button class="card-folder" :aria-label="'打开文件夹 '+g.name" title="打开文件夹" :disabled="!!busy" @click.stop="openFolder(g)" @dblclick.stop><PhFolderOpen :size="18"/></button><button class="card-more" :aria-label="'更多操作 '+g.name" title="更多操作" aria-haspopup="menu" :aria-expanded="menu?.game.id===g.id" :disabled="!!busy" @click.stop="showMenu(g,$event)" @dblclick.stop><PhDotsThree :size="21" weight="bold"/></button></div>
     </article>
    </div>
   </div></section>
  </template></main>
  <footer><span><PhFolderOpen :size="16"/>本地游戏库</span><div><span class="status-dot"></span>{{games.length}} 款游戏<span class="footer-date"> · 扫描于 {{updated.replace('T',' ').slice(0,16)}}</span><button aria-label="设置" @click="openSettings()"><PhGearSix :size="18"/></button></div></footer>
  <Transition name="toast"><div v-if="notice" class="toast" role="status"><PhCheckCircle :size="20" weight="fill"/>{{notice}}</div></Transition><div v-if="error&&!editing" class="error-banner" role="alert">{{error}}<button aria-label="关闭错误提示" @click="error=''"><PhX :size="18"/></button></div>
  <div v-if="editing" class="drawer-backdrop" @click.self="!busy&&(editing=null)"><section role="dialog" aria-modal="true" aria-labelledby="edit-title" class="editor modal editor-drawer"><header><div><p>{{editTab==='review'?'确认游戏资料':'游戏资料'}}</p><h2 id="edit-title">{{editing.name}}</h2></div><button class="icon-button" aria-label="关闭编辑" :disabled="!!busy" @click="editing=null"><PhX :size="22"/></button></header><nav class="editor-tabs" aria-label="编辑分类"><button v-for="item in [...(editing.review?.pending?[{id:'review',name:'待确认'}]:[]),{id:'basic',name:'基本资料'},{id:'cover',name:'封面'},{id:'background',name:'背景图'}]" :key="item.id" :class="{active:editTab===item.id}" :aria-pressed="editTab===item.id" :disabled="!!busy" @click="editTab=item.id">{{item.name}}</button></nav><div class="editor-scroll"><p v-if="error" class="inline-error" role="alert">{{error}}</p><ReviewCandidates v-if="editTab==='review'" :game="editing" :candidates="candidates" :selected="reviewSelection" :disabled="!!busy" @select="reviewSelection=$event" @open="openURL"/><div v-show="editTab==='basic'" class="editor-main"><img v-if="editing.image" class="editor-cover" :src="editing.image" :alt="editing.name"><div class="editor-fields"><label>显示名称<input v-model="editName" maxlength="200" aria-label="显示名称"></label><label>启动程序<select v-model="editExe" aria-label="启动程序"><option v-for="exe in editing.executables" :key="exe" :value="exe">{{exe.split(/[\\/]/).pop()}}</option></select></label><div class="editor-meta">{{editing.detected_appid?'本地 Steam AppID：'+editing.detected_appid:'扫描名称：'+editing.original_name}}</div><div class="editor-commands"><button class="secondary small" :disabled="!!busy" @click="upload"><PhUploadSimple :size="17"/>上传封面</button><button v-if="editing.metadata?.source_url" class="text-button" @click="openURL(editing!.metadata!.source_url)">资料来源<PhArrowSquareOut :size="15"/></button></div></div></div><div v-show="editTab==='background'" class="background-section"><div class="lookup-heading"><h3>背景图来源</h3><span>独立保存，不改变名称和封面</span></div><img v-if="editing.hero_image" class="background-preview" :src="editing.hero_image" alt="当前游戏宽幅背景"><label class="artwork-source">选择来源<select v-model="backgroundProvider" aria-label="背景图片来源" :disabled="!!busy"><option value="steam">Steam 正式原画（优先）</option><option value="steamgriddb">SteamGridDB · 社区图片</option></select></label><p v-if="backgroundProvider==='steam'" class="artwork-note">自动补全优先使用 Steam 正式原画，SteamGridDB 图片由你核对后选择。</p><ArtworkPicker v-if="backgroundProvider==='steamgriddb'" :game-id="editing.id" :initial-query="backgroundQuery" kind="background" @used="artworkUsed('background')" @busy="artworkBusy" @settings="openSettings"/><div v-if="backgroundProvider==='steam'" class="lookup-controls"><input v-model="backgroundQuery" aria-label="背景查询关键词" placeholder="Steam AppID 或游戏名称" @keydown.enter="findBackground"><button class="secondary small" :disabled="!!busy||!backgroundQuery.trim()" @click="findBackground">{{busy==='background'?'查找中…':'查找正式背景'}}</button></div><p v-if="backgroundProvider==='steam'" class="lookup-message">{{backgroundResult?.message||'优先查找 Steam 官方宽幅原画，找不到时保留现有图片。'}}</p><button v-if="editing.background?.source_url" class="text-button small" @click="openURL(editing!.background.source_url!)">背景来源<PhArrowSquareOut :size="14"/></button><div v-if="backgroundProvider==='steam'&&backgroundResult?.candidates?.length" class="candidates"><article v-for="c in backgroundResult.candidates" :key="c.key"><div><h4>{{c.name||c.key}}</h4><p>{{c.provider}} · {{c.key.replace('steam:','AppID ')}}</p><button class="text-button" @click="openURL(c.url)">查看作品<PhArrowSquareOut :size="13"/></button></div><button class="secondary small" :disabled="!!busy" @click="chooseBackground(c)">使用该作品背景</button></article></div></div><div v-show="editTab==='cover'" class="lookup-section"><p class="artwork-note">当前封面来源：{{editing.metadata?.cover_provider||editing.metadata?.provider||'本地图片'}}</p><div class="cover-upload"><img v-if="editing.image" :src="editing.image" :alt="editing.name"><button class="secondary small" :disabled="!!busy" @click="upload"><PhUploadSimple :size="17"/>上传封面</button></div><div class="lookup-heading"><h3>查找名称和封面</h3><span>{{provider==='steamgriddb'?'先确认对应作品，再挑选封面':provider==='dlsite'?'先从外部搜索查找 RJ 编号，再获取 DLsite 官方资料':'优先使用 AppID 或 RJ 编号精确匹配'}}</span></div><div class="lookup-controls"><select v-model="provider" aria-label="查询来源" :disabled="!!busy"><option value="all">全部来源 · 综合匹配</option><option value="steam">Steam</option><option value="vndb">VNDB</option><option value="dlsite">DLsite</option><option value="steamgriddb">SteamGridDB</option></select><input v-if="provider!=='steamgriddb'" v-model="lookup" aria-label="查询关键词" placeholder="名称 / Steam AppID / 商店链接 / RJ 编号" @keydown.enter="search"><button v-if="provider!=='steamgriddb'" class="primary small" :disabled="!!busy||!lookup.trim()" @click="search"><PhSpinnerGap v-if="busy==='search'" :size="17" class="spinning"/><PhMagnifyingGlass v-else :size="17"/>{{busy==='search'?(provider==='dlsite'?'查找 RJ / 资料中…':'查询中'):'查询'}}</button></div><ArtworkPicker v-if="provider==='steamgriddb'" :game-id="editing.id" :initial-query="lookup" kind="cover" @used="artworkUsed('cover')" @busy="artworkBusy" @settings="openSettings"/><button v-if="provider==='dlsite'&&lookup.trim()" class="text-button" @click="openURL('https://www.dlsite.com/maniax/fsr/=/keyword/'+encodeURIComponent(lookup.trim()).replace(/%20/g,'+')+'/order/trend_d/per_page/30')">打开 DLsite 搜索<PhArrowSquareOut :size="14"/></button><p v-if="provider!=='steamgriddb'&&lookupMessage" class="lookup-message">{{lookupMessage}}</p><div v-if="provider!=='steamgriddb'&&candidates.length" class="candidates"><article v-for="c in candidates" :key="c.key"><img v-if="c.image" :src="c.image" :alt="c.name" referrerpolicy="no-referrer"><div><h4>{{c.name}}</h4><p>{{c.provider}} · {{c.score?('匹配度 '+Math.min(100,Math.round(c.score*100))+'%'):c.exact?'编号或名称一致':'候选，需核对'}}</p><button class="text-button" @click="openURL(c.url)">查看作品<PhArrowSquareOut :size="13"/></button></div><button class="secondary small" :disabled="!!busy" @click="choose(c)">{{busy==='choose'?'保存中…':'使用封面'}}</button></article></div></div></div><div v-if="editTab==='review'" class="modal-footer review-footer"><button v-glass class="secondary small" :disabled="!!busy" @click="keepReview">保留原资料</button><button class="primary small" :disabled="!!busy||!reviewSelection" @click="confirmReview">{{busy==='choose'?'保存中…':'确认并应用'}}</button></div><div v-else class="modal-footer"><button class="text-button muted" :disabled="!!busy" @click="reset">恢复扫描资料</button><div><button class="secondary small" :disabled="!!busy" @click="editing=null">取消</button><button class="primary small" :disabled="!!busy||!editName.trim()" @click="save">保存修改</button></div></div></section></div>
  <div v-if="menu" class="game-menu" role="menu" :aria-label="menu.game.name+' 操作'" :style="{left:menu.x+'px',top:menu.y+'px'}" @keydown="menuKeys"><p>{{menu.game.name}}</p><button role="menuitem" @click="menuAction('launch')"><PhPlay :size="17"/>开始游戏</button><button role="menuitem" @click="menuAction('edit')"><PhPencilSimple :size="17"/>编辑资料</button><button role="menuitem" @click="menuAction('background')"><PhMagnifyingGlass :size="17"/>查找正式背景</button><button role="menuitem" @click="menuAction('folder')"><PhFolderOpen :size="17"/>打开文件夹</button><button role="menuitem" @click="menuAction('favorite')"><PhHeart :size="17" :weight="menu.game.favorite?'fill':'regular'"/>{{menu.game.favorite?'取消收藏':'收藏游戏'}}</button></div>
  <div v-if="settings" class="modal-backdrop" @click.self="!busy&&(settings=false)"><section class="modal settings" role="dialog" aria-modal="true" aria-labelledby="settings-title"><header><h2 id="settings-title">设置</h2><button class="icon-button" aria-label="关闭设置" :disabled="!!busy" @click="settings=false"><PhX :size="22"/></button></header><h3>外观</h3><p>选择主题，或与 Windows 的亮暗设置保持一致。</p><div class="theme-options"><button v-for="o in themes" :key="o.value" :class="{active:theme===o.value}" @click="changeTheme(o.value)"><component :is="o.icon" :size="24"/>{{o.name}}<PhCheck v-if="theme===o.value" :size="16"/></button></div><ScanSettings :disabled="!!busy" @busy="value=>busy=value?'scan-settings':''"/><div class="api-settings"><h3>图片来源 · SteamGridDB</h3><p>用于查找封面和宽幅背景。密钥仅加密保存在本机，已保存的内容不会显示。</p><label>API Key<input v-model="apiKey" type="password" aria-label="SteamGridDB API Key" :placeholder="apiStatus.configured?'已保存；填写新密钥可替换':'粘贴你的 SteamGridDB API Key'" maxlength="256" autocomplete="off" :spellcheck="false" :disabled="!!busy"></label><div class="api-commands"><button class="primary small" :disabled="!!busy||!apiKey.trim()" @click="saveAPI">保存密钥</button><button class="secondary small" :disabled="!!busy||(!apiKey.trim()&&!apiStatus.configured)" @click="testAPI">{{busy==='api-test'?'测试中…':'测试连接'}}</button><button class="text-button" :disabled="!!busy||!apiStatus.configured" @click="clearAPI">清除密钥</button></div><p class="api-status" role="status">{{apiMessage||apiStatus.message}}</p><button class="text-button" @click="openURL('https://www.steamgriddb.com/profile/preferences/api')">获取 API Key<PhArrowSquareOut :size="14"/></button></div><h3>游戏资料</h3><p>名称、封面和偏好设置均保存在本机。原网页数据作为备份保留。</p><div class="data-path"><code>{{dataDir}}</code><button class="icon-button" aria-label="复制资料路径" @click="copy(dataDir)"><PhCopy :size="19"/></button></div><p class="settings-note">扫描只更新游戏清单，不覆盖手动填写的名称和封面。</p></section></div>
 </div>
</template>
